import { afterAll, afterEach, beforeAll } from "vitest";

import { env } from "cloudflare:workers";

import { applyD1Migrations } from "cloudflare:test";

import { network } from "./network";

/*
 * Derive the migration-array type directly from Cloudflare's API.
 *
 * Do not duplicate Cloudflare's D1Migration interface locally.
 */
type TestMigrations = Parameters<typeof applyD1Migrations>[1];

/*
 * TEST_MIGRATIONS exists only in our Miniflare integration environment.
 *
 * It is intentionally not part of the production Worker Env generated by
 * `wrangler types`.
 */
type IntegrationTestEnv = typeof env & {
  TEST_MIGRATIONS: TestMigrations;
};

const testEnv = env as IntegrationTestEnv;

/*
 * Enable outbound HTTP interception before integration tests execute.
 *
 * Then apply the actual IncidentPilot D1 migration chain.
 */
beforeAll(async () => {
  network.enable();

  await applyD1Migrations(testEnv.DB, testEnv.TEST_MIGRATIONS);
});

/*
 * Every integration test starts with zero custom network handlers.
 *
 * This is critical for test isolation:
 *
 * a mocked GitHub 500 in one test must never leak into another test.
 */
afterEach(() => {
  network.resetHandlers();
});

/*
 * Cleanly disable the network interceptor after this integration-test file
 * environment finishes.
 */
afterAll(() => {
  network.disable();
});
